fn extract(condition: Vec<bool>, arr: Vec<f32>) -> Vec<f32> {
    // Ensure both vectors have the same length
    assert_eq!(condition.len(), arr.len(), "Input vectors must have equal lengths");
    
    // Count the number of true values in the condition
    let true_count = condition.iter().filter(|&&b| b).count();
    
    // Pre-allocate result vector with the exact capacity needed
    let mut result = Vec::with_capacity(true_count);
    
    // Iterate through both vectors simultaneously
    for (i, &cond) in condition.iter().enumerate() {
        if cond {
            result.push(arr[i]);
        }
    }
    
    // Verify the result length matches the count of true values
    assert_eq!(result.len(), true_count, "Result length must equal true count");
    
    result
}